      H.buff({ id: 'hfield', name: '强谐振场·防御', stats: [{ key: 'defPct', value: 0.2 }], duration: 25, target: 'team', trigger: { on: 'manual' }, mode: 'module', text: '强谐振场：附近队伍中所有角色防御提升20%' });
